// Pack saves generated by make-checkpoint.ts at an OLD commit into tests/fixtures/saves/compat/<tag>-*.
//   npx tsx tools/qa/r28-pack-compat.ts <generated-dir> <tag> <out-dir> <label,label,...>
// Campaign presets go into one `<tag>-campaign.json` ({ "L2": "<stored string>", ... }); every other label becomes
// `<tag>-<label>.json.gz` holding the plain save JSON (the gzip1/checkpoint1 localStorage wrapper is removed, so the
// fixture is independent of the storage encoding and decodeSave still sees the old save content verbatim).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { gunzipSync, gzipSync } from 'node:zlib';
import { gunzipSync as fflateGunzip, strFromU8, strToU8 } from 'three/addons/libs/fflate.module.js';

const [dir, tag, out, labels = ''] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const storedOf = (label: string) => gunzipSync(readFileSync(`${dir}/${label}.json.gz`)).toString();
function plain(stored: string): string {
  if (stored.startsWith('minor-incident.gzip1:')) stored = strFromU8(fflateGunzip(strToU8(stored.slice(21), true)));
  if (stored.startsWith('minor-incident.checkpoint1:')) {
    const [campaign, view, current] = JSON.parse(stored.slice(27));
    return JSON.stringify({ ...campaign, cureResume: { ...view, current, checkpoint: '$same' } }); // identical retry copy; the test expands '$same'
  }
  return stored;
}
const campaign: Record<string, string> = {};
for (let n = 2; n <= 10; n++) campaign[`L${n}`] = storedOf(`campaign-L${n}-default`);
writeFileSync(`${out}/${tag}-campaign.json`, JSON.stringify(campaign, null, 1));
for (const label of labels.split(',').filter(Boolean)) {
  const bytes = gzipSync(plain(storedOf(label)), { level: 9 });
  writeFileSync(`${out}/${tag}-${label}.json.gz`, bytes);
  console.log(label, bytes.length, 'B');
}
